import subprocess
import time

def get_pane():
    res = subprocess.run(['tmux', 'capture-pane', '-e', '-p', '-t', 'typing'], capture_output=True, text=True)
    return res.stdout.split('\n')

all_words = []

def extract_untyped(lines):
    for i, line in enumerate(lines):
        if "│" in line and "│" in line.rpartition("│")[0] and i > 5 and i < 15:
