                    clean = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', content).strip()
                    if clean and not any(x in clean for x in ['┌', '│', '└', ' ' * 5]):
                        # extract remaining words by checking what's not bold/green
                        # But simpler: just get the full line of text, split by space.
                        return clean.split()
    return []

print(extract_untyped(get_pane()))
