import sys
import subprocess
import time
import re

def get_screen():
    res = subprocess.run(['tmux', 'capture-pane', '-p', '-e', '-t', 'typing'], capture_output=True, text=True)
    return res.stdout.split('\n')

lines = get_screen()
# Find the text line
text = ""
for line in lines[5:15]:
    clean = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line).strip()
    if clean.startswith('│') and clean.endswith('│') and 'Lesson' not in clean and 'WPM' not in clean and 'Acc' not in clean:
        content = clean[1:-1].strip()
        if content:
            text = content
            break

print("TEXT:", text)
words = text.split()
for i, w in enumerate(words):
    for char in w:
        subprocess.run(['tmux', 'send-keys', '-t', 'typing', char])
    if i < len(words) - 1:
        subprocess.run(['tmux', 'send-keys', '-t', 'typing', ' '])
    time.sleep(0.05)

print("Finished words. Checking screen...")
time.sleep(0.5)
lines = get_screen()
for line in lines[5:15]:
    clean = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line).strip()
    if clean.startswith('│') and clean.endswith('│') and 'Lesson' not in clean and 'WPM' not in clean and 'Acc' not in clean:
        content = clean[1:-1].strip()
        if content:
            print("NEW TEXT:", content)
            break
