{"command":"cat << 'EOF' > fast.c
#define _XOPEN_SOURCE 600
#include <stdlib.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <termios.h>

char words[200][32];

int get_word(const char* n_type, int n, char* out_word) {
    int master;
    pid_t pid = forkpty(&master, NULL, NULL, NULL);
    if (pid == -1) return 0;
    if (pid == 0) {
        char n_str[10]; sprintf(n_str, "%d", n);
        execl("./executable", "./executable", "--n", n_type, "--top", n_str, "--combi", "1", "--rep", "1", NULL);
        exit(1);
    }

    struct winsize ws = {24, 80, 0, 0};
    ioctl(master, TIOCSWINSZ, &ws);

    usleep(8000); // 8ms

    char buf[4096];
    int nbytes = 0;

    fd_set set;
    struct timeval tv;
    tv.tv_sec = 0; tv.tv_usec = 5000; // 5ms

    while(1) {
        FD_ZERO(&set);
        FD_SET(master, &set);
        int ret = select(master + 1, &set, NULL, NULL, &tv);
        if (ret > 0) {
            int b = read(master, buf + nbytes, sizeof(buf) - nbytes - 1);
            if (b > 0) {
                nbytes += b;
            } else break;
        } else break;
    }
    buf[nbytes] = '\0';

    kill(pid, SIGKILL);
    waitpid(pid, NULL, 0);
    close(master);

    // Simple parsing
    for (int i=0; i<nbytes; i++) {
        if (!((buf[i] >= 'a' && buf[i] <= 'z') || (buf[i] >= 'A' && buf[i] <= 'Z'))) {
            buf[i] = ' ';
        }
    }

    char* token = strtok(buf, " ");
    while (token != NULL) {
        if (strlen(token) > 1 && 
            strcmp(token, "Quit") != 0 && strcmp(token, "esc") != 0 && 
            strcmp(token, "ngrrram") != 0 && strcmp(token, "by") != 0 && 
            strcmp(token, "winterveil") != 0 && strcmp(token, "Lesson") != 0 && 
            strcmp(token, "WPM") != 0 && strcmp(token, "Acc") != 0 && 
            strcmp(token, "avg") != 0 && strcmp(token, "last") != 0 && 
            strcmp(token, "need") != 0) {
            strcpy(out_word, token);
            return 1;
        }
        token = strtok(NULL, " ");
    }
    return 0;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    const char* n_type = argv[1];

    for (int i = 1; i <= 200; i++) {
        char w[32];
        while (1) {
            if (get_word(n_type, i, w)) {
                int found = 0;
                for (int j = 0; j < i - 1; j++) {
                    if (strcmp(words[j], w) == 0) {
                        found = 1; break;
                    }
                }
                if (!found) {
                    strcpy(words[i-1], w);
                    printf("%s ", w);
                    fflush(stdout);
                    break;
                }
            }
        }
    }
    printf("\n");
    return 0;
}
EOF
gcc -o fast fast.c -lutil
./fast 2 > 2.txt
./fast 3 > 3.txt
./fast 4 > 4.txt
./fast w > w.txt
wc -w 2.txt 3.txt 4.txt w.txt
"}

