#define _XOPEN_SOURCE 600
#include <stdlib.h>
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <pty.h>
#include <sys/select.h>

char words[200][32];
char batch_words[20][32];

int get_words(const char* n_type, int n, int combi) {
    int master;
    pid_t pid = forkpty(&master, NULL, NULL, NULL);
    if (pid == -1) return 0;
    if (pid == 0) {
        char n_str[10], c_str[10]; 
        sprintf(n_str, "%d", n);
        sprintf(c_str, "%d", combi);
        execl("./executable", "./executable", "--n", n_type, "--top", n_str, "--combi", c_str, "--rep", "1", "--nokb", NULL);
        exit(1);
    }

    struct winsize ws = {24, 80, 0, 0};
    ioctl(master, TIOCSWINSZ, &ws);

    usleep(2000);

    char buf[4096];
    int nbytes = 0;

    struct timeval tv;
    fd_set set;

    while(1) {
        tv.tv_sec = 0; tv.tv_usec = 5000;
        FD_ZERO(&set);
        FD_SET(master, &set);
        int ret = select(master + 1, &set, NULL, NULL, &tv);
        if (ret > 0) {
            int b = read(master, buf + nbytes, sizeof(buf) - nbytes - 1);
            if (b > 0) {
                nbytes += b;
            } else break;
        } else break;
    }
    buf[nbytes] = '\0';
    kill(pid, SIGKILL);
    waitpid(pid, NULL, 0);
    close(master);

    char clean[4096];
    int j = 0;
    for (int i=0; i<nbytes; i++) {
        if (buf[i] == '\x1b') {
            i++;
            while (i < nbytes) {
                char c = buf[i];
                if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) break;
                i++;
            }
        } else {
            clean[j++] = buf[i];
        }
    }
    clean[j] = '\0';

    for (int i=0; i<j; i++) {
        if (!((clean[i] >= 'a' && clean[i] <= 'z') || (clean[i] >= 'A' && clean[i] <= 'Z'))) {
            clean[i] = ' ';
        }
    }

    int count = 0;
    char* token = strtok(clean, " ");
    while (token != NULL) {
        if (strcmp(token, "Quit") != 0 && strcmp(token, "esc") != 0 && 
            strcmp(token, "ngrrram") != 0 && strcmp(token, "by") != 0 && 
            strcmp(token, "winterveil") != 0 && strcmp(token, "Lesson") != 0 && 
            strcmp(token, "WPM") != 0 && strcmp(token, "Acc") != 0 && 
            strcmp(token, "avg") != 0 && strcmp(token, "last") != 0 && 
            strcmp(token, "need") != 0) {
            if (count < 20) strcpy(batch_words[count++], token);
        }
        token = strtok(NULL, " ");
    }
    return count;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    const char* n_type = argv[1];
    int combi = 12;
    if (n_type[0] == 'w') combi = 8;

    for (int i = 1; i <= 200; i++) {
        int actual_combi = i < combi ? i : combi;
        int tries = 0;
        int found_new = 0;
        char new_word[32];

        while (tries < 500) {
            int c = get_words(n_type, i, actual_combi);
            for (int k = 0; k < c; k++) {
                int found = 0;
                for (int j = 0; j < i - 1; j++) {
                    if (strcmp(words[j], batch_words[k]) == 0) {
                        found = 1; break;
                    }
                }
                if (!found) {
                    found_new = 1;
                    strcpy(new_word, batch_words[k]);
                    break;
                }
            }
            if (found_new) break;
            tries++;
        }

        if (!found_new) break;
        else {
            strcpy(words[i-1], new_word);
            printf("%s ", new_word);
            fflush(stdout);
        }
    }
    printf("\n");
    return 0;
}
